window.docContents[7].resolve({"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software":{"contents":"DLMF §4.48 is a curated software bibliography, organized by the kind of\narithmetic or function support supplied. It deliberately omits software that\nuses only standard floating-point arithmetic. The page has no numbered\nmathematical formulas: the entries below preserve its resource categories,\nlanguages, references, and editorial additions.\n\n\n\n\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions\u0009§4.48 Software","header":"§4.48 Software","id":"/Elementary-Functions/___4___48-Software/#LMLF-___-DLMF-with-Lean--Elementary-Functions--___4___48-Software--___4___48-Software"}});